 put(out.bytes,state.control.current,2);put(out.bytes,state.control.pending,2);put(out.bytes,state.control.activationMode,1);const std::vector<uint16_t>* vectors[]={&state.control.available,&state.control.selected,&state.control.activations,&state.control.history};for(const std::vector<uint16_t>* values:vectors){put(out.bytes,values->size(),1);for(uint16_t value:*values)put(out.bytes,value,2);}
 put(out.bytes,state.work.size(),2);put(out.bytes,state.locals.size(),1);put(out.bytes,state.returns.size(),1);put(out.bytes,state.requests.size(),out.bytes[4]>=5?2:1);for(const NarrativeWork& work:state.work){cursorPut(out.bytes,work.cursor);put(out.bytes,work.action,1);put(out.bytes,work.saved,4);}for(uint32_t local:state.locals)put(out.bytes,local,4);for(Cursor value:state.returns)cursorPut(out.bytes,value);
