 next.control.current=uint16_t(reader.get(2));next.control.pending=uint16_t(reader.get(2));unsigned activation=unsigned(reader.get(1));if(activation>1){error="narrative payload activation flag";return false;}next.control.activationMode=activation!=0;std::vector<uint16_t>* vectors[]={&next.control.available,&next.control.selected,&next.control.activations,&next.control.history};const unsigned limits[]={31,15,8,3};for(unsigned i=0;i<4;++i){size_t count=size_t(reader.get(1));if(count>limits[i]){error="narrative payload control capacity";return false;}for(size_t j=0;j<count;++j)vectors[i]->push_back(uint16_t(reader.get(2)));}
